/**
 * SEO-2 — the ט׳ מצומצמת hub (/grade-9-reduced), the "לפי הפריסה" month
 * index on /grade-7, /grade-8 and /grade-9, and optional TopicPage section
 * anchors. Data comes from src/data/prisa-units.v1.json, generated by
 * scripts/build-prisa-units.ts from scripts/data/prisa (a snapshot of the
 * curriculum mapping all-units.csv, the official prisa PDF months, and the
 * topic pages per unit).
 *
 * The request-time code never throws on a missing or moved page or anchor; it
 * renders plain text and logs. The strict checks live here, so CI fails.
 */
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { basename, dirname, resolve } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { transform as compileAstro } from '@astrojs/compiler';
import { experimental_AstroContainer as AstroContainer } from 'astro/container';
import { build } from 'esbuild';
import { parseHTML } from 'linkedom';
import {
  PRISA_MONTH_KEYS,
  PRISA_TRACK_KEYS,
  REDUCED_HUB_PATH,
  currentPrisaMonthKey,
  loadPrisaTrack,
  pageLabelWithoutGrade,
  prisaHrefs,
  prisaItemListJsonLd,
  prisaTracksForGrade,
  resolvePrisaPage,
  unitCountLabel,
} from '../src/lib/prisaIndex.ts';
import {
  TOPIC_PAGE_SLUGS,
  loadAllTopicPages,
  loadTopicPage,
  synthesizeBodyFlow,
  topicSectionAnchorProblems,
  validateTopicSectionAnchors,
  type TopicPageContent,
} from '../src/lib/topicPages.ts';
import { groupTopicBodyFlow } from '../src/lib/topicPageCtas.ts';
import { prisaPageRefProblem } from '../src/lib/prisaPageRef.ts';
import { PRISA_UNITS_OUTPUT, buildPrisaUnitsJson, readUnitPagesInput } from '../scripts/build-prisa-units.ts';
import kiteGrade9 from '../src/data/topic-pages/kite-grade-9.json';
import { resolveSiteHref } from '../src/lib/resolveSiteHref.ts';
import { resolveActiveNav, resolveWorksheetsNavBand } from '../src/lib/activeNav.ts';
import { renderPagesSitemapXml } from '../src/lib/siteSitemaps.ts';
import { SITE_CANONICAL_ORIGIN } from '../src/lib/siteSeo.ts';
import { breadcrumbList, jsonLdTypes, validateJsonLdDocument } from '../src/lib/structuredData.ts';

const require = createRequire(import.meta.url);
const fromTest = (rel: string) => fileURLToPath(new URL(rel, import.meta.url));
const raw = JSON.parse(readFileSync(fromTest('../src/data/prisa-units.v1.json'), 'utf8'));
const NOW = new Date('2026-11-17T10:00:00Z');

/**
 * Units with no same-grade page at 118b4d90 (the mapping's no_topic units,
 * minus the triangle inequality, which batch 2a added to the median page, and
 * minus st.g9m.equations.numeric_denominator, whose planned landing
 * equations-numeric-denominator-grade-9 is served since the content train, and minus the six
 * units whose planned NEW4 landings are served since 18 Nov).
 * A new landing may only shrink this list, after a regenerate.
 */
const NO_PAGE_UNITS = [
  // NEW4 (18.11) serves the planned landings of the grade-8 transformations unit, the four
  // grade-9 parallel-lines units and the grade-9 literacy unit.
  'st.g9m.percentages.part_of_whole',
  'st.g9m.percentages.increase_decrease',
  'st.g9m.parallels_and_parallelogram.review',
  'st.g9m.word_problems_integrative.literacy_contexts',
];

describe('prisa data (generated from scripts/data/prisa)', () => {
  it('records each source path and sha256, and the build reads only this file', () => {
    assert.equal(raw.schema, 'noam-prisa-units/v1');
    assert.equal(raw.sources.units.path, 'headless/astro-poc/scripts/data/prisa/all-units.fields.v1.json');
    assert.equal(raw.sources.units.origin.path, 'פרויקט החלפת דפי חטיבת הביניים/reports/curriculum-mapping-20261116/all-units.csv');
    assert.equal(raw.sources.units.origin.sha256, 'ea7641d4a492833a933c4e4f9d05d49b2f206c0755c771b479d09753fa9e232e');
    assert.equal(raw.sources.units.rows, 173);
    assert.equal(raw.sources.months.path, 'headless/astro-poc/scripts/data/prisa/layout.v1.json');
    assert.equal(raw.sources.landings.path, 'headless/astro-poc/scripts/data/prisa/unit-pages.v1.json');
    assert.match(raw.sources.landings.origin.coverage.sha256, /^[0-9a-f]{64}$/);
    assert.match(raw.sources.landings.origin.corrections.sha256, /^[0-9a-f]{64}$/);
    for (const key of ['units', 'months', 'landings'] as const) {
      const input = raw.sources[key].path.replace(/^headless\/astro-poc\//, '../');
      assert.ok(readFileSync(fromTest(input), 'utf8').length > 1000, input);
    }
    const prisa = { g7: 'prisa_7.pdf', g8: 'prisa_8.pdf', g9r: 'prisa_9A.pdf', g9m: 'prisa_9B.pdf' } as const;
    for (const track of raw.tracks) {
      assert.equal(
        track.source.url,
        `https://meyda.education.gov.il/files/Pop/0files/matmatika/Chativat-Beynayim/tashpaz/${prisa[track.key as keyof typeof prisa]}`
      );
      assert.match(track.source.sha256, /^[0-9a-f]{64}$/);
    }
    // No absolute local path ships in the bundle; no runtime read of the source.
    assert.equal(JSON.stringify(raw).includes('/Users/'), false);
    for (const rel of ['../src/lib/prisaIndex.ts', '../src/lib/prisaPageRef.ts']) {
      assert.doesNotMatch(readFileSync(fromTest(rel), 'utf8'), /node:fs|readFileSync|process\.cwd|from '[^']*scripts\//, rel);
    }
  });

  it('has all 173 units once: ז 49, ח 37, ט רגילה 48, ט מצומצמת 39', () => {
    const counts = Object.fromEntries(PRISA_TRACK_KEYS.map((k) => [k, loadPrisaTrack(k).unitCount]));
    assert.deepEqual(counts, { g7: 49, g8: 37, g9r: 48, g9m: 39 });
    const ids = raw.tracks.flatMap((t: any) => t.months.flatMap((m: any) => m.units.map((u: any) => u.id)));
    assert.equal(ids.length, 173);
    assert.equal(new Set(ids).size, 173);
    const prefix = { g7: 'st.g7.', g8: 'st.g8.', g9r: 'st.g9r.', g9m: 'st.g9m.' } as Record<string, string>;
    for (const track of raw.tracks) {
      for (const month of track.months) {
        for (const unit of month.units) assert.ok(unit.id.startsWith(prefix[track.key]), unit.id);
      }
    }
  });

  it('lists months in school-year order, none empty, with official names and no slash fractions', () => {
    for (const track of raw.tracks) {
      const keys = track.months.map((m: any) => m.key);
      const order = keys.map((k: string) => PRISA_MONTH_KEYS.indexOf(k as any));
      assert.ok(order.every((i: number) => i >= 0), `${track.key} month keys`);
      assert.deepEqual(order, [...order].sort((a, b) => a - b), `${track.key} month order`);
      assert.equal(new Set(keys).size, keys.length);
      for (const month of track.months) {
        assert.ok(month.units.length > 0, `${track.key} ${month.key} is empty`);
        assert.ok(Number.isInteger(month.prisaPage) && month.prisaPage >= 2);
        for (const unit of month.units) {
          assert.ok(unit.name.trim().length > 3, unit.id);
          assert.equal(unit.name.includes('/'), false, `${unit.id} writes a slash`);
          if (unit.note) assert.equal(unit.note.includes('/'), false, unit.id);
        }
      }
    }
  });

  it('places reduced-track units in the prisa_9B months (verify.json corrections)', () => {
    const track = loadPrisaTrack('g9m');
    const monthOf = (id: string) => track.months.find((m) => m.units.some((u) => u.id === id))!.key;
    assert.deepEqual(track.months.map((m) => m.key), ['m09', 'm10', 'm11', 'm12', 'm01', 'm02', 'm03', 'm04', 'm05']);
    // prisa_9B p4: משוואות עם מכנה מספרי in ינואר (not the registry's topic-18 slot).
    assert.equal(monthOf('st.g9m.equations.numeric_denominator'), 'm01');
    assert.equal(monthOf('st.g9m.percentages.part_of_whole'), 'm11');
    assert.equal(monthOf('st.g9m.graph_reading.phenomena_axes'), 'm09');
    assert.equal(monthOf('st.g9m.areas_and_perimeters.polygons_and_circle'), 'm05');
    // prisa_9B p5: the quadratic-function properties are not taught this year.
    const quad = track.months.flatMap((m) => m.units).find((u) => u.id === 'st.g9m.quad_partial.table_and_graph')!;
    assert.equal(quad.primary?.href, '/quadratic-function-grade-9');
    assert.match(quad.note || '', /תכונות הפונקציה הריבועית לא נלמדות השנה/);
    const optional = track.months.flatMap((m) => m.units).filter((u) => u.optional).map((u) => u.id);
    assert.deepEqual(optional, ['st.g9m.linear_function.line_equation_optional']);
  });
});

describe('generator (scripts/build-prisa-units.ts)', () => {
  it('the committed data file is exactly the generator output (else: npx tsx scripts/build-prisa-units.ts)', () => {
    assert.equal(
      readFileSync(PRISA_UNITS_OUTPUT, 'utf8'),
      buildPrisaUnitsJson(),
      'src/data/prisa-units.v1.json is stale. Run: npx tsx scripts/build-prisa-units.ts'
    );
  });

  it('every page slug in the mapping exists as a served topic page of the unit grade (anchors included)', () => {
    const input = readUnitPagesInput();
    const grades: Record<string, number> = { g7: 7, g8: 8, g9r: 9, g9m: 9 };
    const unitGrade = (id: string) => grades[id.split('.')[1]];
    assert.equal(Object.keys(input.units).length, 173);
    const problems: string[] = [];
    for (const [id, entry] of Object.entries(input.units)) {
      assert.ok(unitGrade(id), id);
      for (const ref of entry.pages) {
        const problem = prisaPageRefProblem(ref, unitGrade(id));
        if (problem) problems.push(`${id}: ${problem}`);
      }
      for (const ref of entry.planned || []) {
        assert.equal(entry.pages.includes(ref), false, `${id}: planned ${ref} is already listed`);
      }
    }
    assert.deepEqual(problems, []);
  });

  it('a planned landing is linked first once it is served (a new landing only needs a regenerate)', () => {
    const input = readUnitPagesInput();
    const pagesById = new Map<string, string[]>(
      raw.tracks.flatMap((t: any) => t.months.flatMap((m: any) => m.units.map((u: any) => [u.id, u.pages])))
    );
    const served = new Set<string>(TOPIC_PAGE_SLUGS);
    for (const [id, entry] of Object.entries(input.units)) {
      const live = (entry.planned || []).filter((slug) => served.has(slug));
      assert.deepEqual(pagesById.get(id), [...live, ...entry.pages.filter((p) => !live.includes(p))], id);
    }
  });

  it('links the batch-2a landings merged at 118b4d90', () => {
    const pagesOf = (id: string) =>
      raw.tracks.flatMap((t: any) => t.months.flatMap((m: any) => m.units)).find((u: any) => u.id === id).pages as string[];
    assert.ok(pagesOf('st.g8.triangle_parts.triangle_inequality').includes('triangle-median-grade-8'));
    assert.ok(pagesOf('st.g8.triangle_parts.isosceles_converse').includes('isosceles-triangle-properties-grade-8'));
    assert.ok(pagesOf('st.g9r.powers.sqrt_laws').includes('exponent-rules-grade-9'));
    assert.ok(pagesOf('st.g9m.pythagoras.composite_areas_perim').includes('pythagorean-theorem-grade-9'));
  });

  it('links the first planned landing that became a served page (content train, topic 9/49)', () => {
    const id = 'st.g9m.equations.numeric_denominator';
    const slug = 'equations-numeric-denominator-grade-9';
    const input = readUnitPagesInput();
    // The input still names it as planned only; the generator links it because the page is served.
    assert.deepEqual(input.units[id], { pages: [], planned: [slug] });
    assert.ok(TOPIC_PAGE_SLUGS.includes(slug));
    const reduced = raw.tracks.find((t: any) => t.key === 'g9m');
    const january = reduced.months.find((m: any) => m.key === 'm01');
    assert.equal(january.label, 'ינואר');
    assert.deepEqual(january.units.find((u: any) => u.id === id).pages, [slug]);
    // Batch 4 added PDF sections to four landings; each was already first for the units its section teaches.
    const refresh = (input.origin as any).refresh.at(-1);
    assert.equal(refresh.baseline, '74449462');
    assert.deepEqual(refresh.pages, [{ unit: id, added: slug, position: 'first', section: 'planned landing, linked by the generator once it is served' }]);
    assert.deepEqual(refresh.unchanged, ['kite-grade-9', 'triangle-30-60-90-grade-9', 'solids-box-cube-prism-grade-7', 'similar-triangles-grade-8']);
    const firstPage = (unit: string) => raw.tracks.flatMap((t: any) => t.months.flatMap((m: any) => m.units)).find((u: any) => u.id === unit).pages[0];
    for (const [unit, page] of [
      ['st.g9r.kite.definition_angles', 'kite-grade-9'], ['st.g9r.kite.main_diagonal_area', 'kite-grade-9'],
      ['st.g9m.kite_and_isosceles.kite_properties', 'kite-grade-9'],
      ['st.g9r.right_triangle_30_60_90.theorem_and_converse', 'triangle-30-60-90-grade-9'],
      ['st.g7.solids.triangular_prism', 'solids-box-cube-prism-grade-7'],
      ['st.g8.similarity.similar_polygons_ratio', 'similar-triangles-grade-8'], ['st.g8.similarity.criteria', 'similar-triangles-grade-8'],
    ]) assert.equal(firstPage(unit), page, unit);
  });
});

describe('prisa links', () => {
  it('every page in the data is a served topic page of the same grade, with its anchor', () => {
    const problems: string[] = [];
    for (const track of raw.tracks) {
      for (const month of track.months) {
        for (const unit of month.units) {
          for (const ref of unit.pages) {
            const problem = prisaPageRefProblem(ref, track.grade);
            if (problem) problems.push(`${unit.id}: ${problem}`);
          }
        }
      }
    }
    assert.deepEqual(problems, []);
  });

  it('a unit without a served page is plain text; all others link their first page', () => {
    const noPage: string[] = [];
    for (const key of PRISA_TRACK_KEYS) {
      const rawUnits = new Map<string, string[]>(
        raw.tracks.find((t: any) => t.key === key).months.flatMap((m: any) => m.units.map((u: any) => [u.id, u.pages]))
      );
      for (const unit of loadPrisaTrack(key).months.flatMap((m) => m.units)) {
        const pages = rawUnits.get(unit.id)!;
        if (!unit.primary) {
          noPage.push(unit.id);
          assert.equal(unit.more.length, 0);
          assert.deepEqual(pages, [], `${unit.id} lists pages but renders as plain text`);
        } else {
          assert.equal(unit.primary.href, `/${pages[0]}`);
        }
      }
    }
    // New landings may link more units; none may lose its link.
    for (const id of noPage) assert.ok(NO_PAGE_UNITS.includes(id), `${id} lost its page`);
    assert.ok(loadPrisaTrack('g9m').linkedUnitCount >= 35);
    assert.ok(loadPrisaTrack('g8').linkedUnitCount >= 36);
    assert.ok(loadPrisaTrack('g9r').linkedUnitCount >= 43);
    assert.equal(loadPrisaTrack('g7').linkedUnitCount, 49);
  });

  it('renders a missing or moved target as plain text with a server warning, never a throw', (t) => {
    const warn = t.mock.method(console, 'warn', () => {});
    assert.equal(resolvePrisaPage('no-such-page-grade-9', 9), null);
    assert.equal(resolvePrisaPage('kite-grade-9#no-such-anchor', 9), null);
    assert.equal(resolvePrisaPage('kite-grade-9', 8), null);
    assert.equal(resolvePrisaPage('kite-grade-9#a#b', 9), null);
    const messages = warn.mock.calls.map((c) => String(c.arguments[0]));
    assert.equal(messages.length, 4);
    assert.match(messages[0], /^\[prisa\] grade 9 unit page no-such-page-grade-9: no-such-page-grade-9 is not a served topic page; rendered as plain text$/);
    assert.match(messages[1], /kite-grade-9 has no section anchor #no-such-anchor/);
    assert.match(messages[2], /kite-grade-9 is grade 9, expected 8/);
    assert.match(messages[3], /malformed page ref/);
    // Cached: the warning is logged once per target.
    assert.equal(resolvePrisaPage('no-such-page-grade-9', 9), null);
    assert.equal(warn.mock.calls.length, 4);
    assert.deepEqual(resolvePrisaPage('kite-grade-9', 9), { slug: 'kite-grade-9', href: '/kite-grade-9', label: 'דלתון' });
    assert.equal(warn.mock.calls.length, 4);
  });

  it('every rendered href is a page this site serves (internal-link check)', () => {
    const hrefs = prisaHrefs();
    assert.ok(hrefs.includes(REDUCED_HUB_PATH));
    assert.ok(hrefs.length > 100);
    const broken = hrefs.filter((href) => resolveSiteHref(href).reason !== 'local');
    assert.deepEqual(broken, []);
    for (const href of ['/grade-9#prisa', '/worksheets?grade=9&track=red']) {
      assert.equal(resolveSiteHref(href).reason, 'local', href);
    }
  });

  it('labels the extra-page chips with the topic H1 minus the grade words', () => {
    assert.equal(pageLabelWithoutGrade('זוויות לכיתה ז׳ — היכרות, סימון ומדידה'), 'זוויות — היכרות, סימון ומדידה');
    assert.equal(pageLabelWithoutGrade('סטטיסטיקה לכיתה ח׳: איסוף מידע'), 'סטטיסטיקה: איסוף מידע');
    assert.equal(pageLabelWithoutGrade('שטחים ב׳ חלק 2 — מצולעים מורכבים — לכיתה ט׳'), 'שטחים ב׳ חלק 2 — מצולעים מורכבים');
    assert.equal(pageLabelWithoutGrade('דלתון לכיתה ט׳'), 'דלתון');
    const angles = loadPrisaTrack('g9r').months.flatMap((m) => m.units)
      .find((u) => u.id === 'st.g9r.right_triangle_30_60_90.theorem_and_converse')!;
    assert.equal(angles.name, 'משולש ישר־זווית שזוויותיו 30°, 60°, 90° והמשפט ההפוך');
    assert.equal(angles.displayName, 'משולש ישר־זווית שזוויותיו \u206630°, 60°, 90°\u2069 והמשפט ההפוך');
    assert.equal(unitCountLabel(1), 'נושא אחד');
    assert.equal(unitCountLabel(7), '7 נושאים');
  });

  it('opens the current school month in Israel time; summer points to September', () => {
    assert.equal(currentPrisaMonthKey(NOW), 'm11');
    assert.equal(currentPrisaMonthKey(new Date('2026-11-30T23:30:00Z')), 'm12');
    assert.equal(currentPrisaMonthKey(new Date('2027-07-15T12:00:00Z')), 'm09');
    assert.equal(currentPrisaMonthKey(new Date('2027-08-31T12:00:00Z')), 'm09');
    assert.equal(currentPrisaMonthKey(new Date('2027-01-10T12:00:00Z')), 'm01');
  });

  it('grade hubs: 7 and 8 have one track, 9 has רגילה then מצומצמת; elementary none', () => {
    assert.deepEqual(prisaTracksForGrade(7).map((t) => t.key), ['g7']);
    assert.deepEqual(prisaTracksForGrade(8).map((t) => t.key), ['g8']);
    assert.deepEqual(prisaTracksForGrade(9).map((t) => t.shortLabel), ['ט׳ רגילה', 'ט׳ מצומצמת']);
    assert.deepEqual(prisaTracksForGrade(4), []);
  });
});

describe('/grade-9-reduced route, sitemap, nav and JSON-LD', () => {
  it('is in the pages sitemap, served locally and under the worksheets nav', () => {
    const keys = readdirSync(fromTest('../src/pages')).filter((n) => n.endsWith('.astro')).map((n) => `./${n}`);
    const xml = renderPagesSitemapXml(keys);
    assert.ok(xml.includes(`<loc>${SITE_CANONICAL_ORIGIN}${REDUCED_HUB_PATH}</loc>`));
    assert.equal(resolveSiteHref(REDUCED_HUB_PATH).reason, 'local');
    assert.equal(resolveActiveNav(REDUCED_HUB_PATH), 'worksheets');
    assert.equal(resolveWorksheetsNavBand(REDUCED_HUB_PATH), 'hatzava');
    assert.equal(resolveActiveNav('/grade-9'), 'worksheets');
  });

  it('ItemList lists linked units only, one item per URL, first-seen order, positions 1..n', () => {
    const track = loadPrisaTrack('g9m');
    const ld = prisaItemListJsonLd(track, { name: 'נושאי הפריסה', path: REDUCED_HUB_PATH });
    assert.deepEqual(validateJsonLdDocument(ld), []);
    assert.deepEqual(jsonLdTypes(ld), ['ItemList']);
    assert.equal(ld.url, `${SITE_CANONICAL_ORIGIN}${REDUCED_HUB_PATH}`);
    const items = ld.itemListElement as Array<Record<string, unknown>>;
    const expectedUrls = [
      ...new Set(track.months.flatMap((m) => m.units).filter((u) => u.primary).map((u) => `${SITE_CANONICAL_ORIGIN}${u.primary!.href}`)),
    ];
    assert.equal(ld.numberOfItems, items.length);
    assert.equal(items.length, expectedUrls.length);
    assert.ok(items.length < track.linkedUnitCount, 'several units share a page');
    assert.deepEqual(items.map((i) => i.url), expectedUrls);
    assert.deepEqual(items.map((i) => i.position), Array.from({ length: items.length }, (_, i) => i + 1));
    for (const item of items) {
      assert.equal(item['@type'], 'ListItem');
      assert.ok(typeof item.name === 'string' && (item.name as string).length > 3);
      assert.equal(/[⁦-⁩]/.test(item.name as string), false, 'no bidi isolates in JSON-LD');
      assert.ok(String(item.url).startsWith(`${SITE_CANONICAL_ORIGIN}/`));
    }
    // Both graph-reading units link /reading-graphs-grade-9; the first names the item.
    assert.equal(items[0].name, 'קריאת מידע מגרפים של תופעות במערכת צירים (ספטמבר)');
    assert.equal(items[0].url, `${SITE_CANONICAL_ORIGIN}/reading-graphs-grade-9`);
    assert.equal(items.filter((i) => i.url === items[0].url).length, 1);

    // A synthetic track: unlinked units are skipped, duplicates keep the first, no gaps.
    const unit = (id: string, href: string | null) => ({
      id, name: id, displayName: id, optional: false, more: [],
      primary: href ? { slug: href.slice(1), href, label: id } : null,
    });
    const fake = {
      ...track,
      months: [
        { key: 'm09', label: 'ספטמבר', id: 'x-m09', units: [unit('a', null), unit('b', '/p'), unit('c', '/q')] },
        { key: 'm10', label: 'אוקטובר', id: 'x-m10', units: [unit('d', '/p'), unit('e', null), unit('f', '/r')] },
      ],
    };
    const small = prisaItemListJsonLd(fake, { name: 'x', path: REDUCED_HUB_PATH });
    assert.deepEqual(
      (small.itemListElement as Array<Record<string, unknown>>).map((i) => [i.position, i.name, i.url]),
      [
        [1, 'b (ספטמבר)', `${SITE_CANONICAL_ORIGIN}/p`],
        [2, 'c (ספטמבר)', `${SITE_CANONICAL_ORIGIN}/q`],
        [3, 'f (אוקטובר)', `${SITE_CANONICAL_ORIGIN}/r`],
      ]
    );
    assert.equal(small.numberOfItems, 3);
    const crumbs = breadcrumbList([
      { name: 'בית', path: '/' },
      { name: 'כיתה ט׳', path: '/grade-9' },
      { name: 'ט׳ מצומצמת', path: REDUCED_HUB_PATH },
    ]);
    assert.deepEqual(validateJsonLdDocument(crumbs), []);
  });
});

describe('TopicPage section anchors (optional, back-compatible)', () => {
  function rawPage(slug: string): TopicPageContent {
    return JSON.parse(readFileSync(fromTest(`../src/data/topic-pages/${slug}.json`), 'utf8'));
  }

  it('no current topic page declares an anchor, so every H2 renders as before', () => {
    for (const page of loadAllTopicPages()) {
      const headings = synthesizeBodyFlow(page).filter((b) => b.type === 'heading');
      assert.ok(headings.every((b) => !('anchor' in b)), page.slug);
    }
  });

  it('every topic page passes the strict anchor rules (enforced here, not at request time)', () => {
    const problems: string[] = [];
    for (const slug of TOPIC_PAGE_SLUGS) {
      try {
        validateTopicSectionAnchors(rawPage(slug));
      } catch (error) {
        problems.push((error as Error).message);
      }
    }
    assert.deepEqual(problems, []);
    const lib = readFileSync(fromTest('../src/lib/topicPages.ts'), 'utf8');
    const loader = lib.slice(lib.indexOf('export function loadTopicPage('), lib.indexOf('export function loadAllTopicPages('));
    assert.doesNotMatch(loader, /validateTopicSectionAnchors\(/);
    assert.match(loader, /topicSectionAnchorProblems\(data\)/);
  });

  it('a page without anchors is not synthesized during the anchor check', () => {
    const untouchable = (target: Record<string, unknown>) =>
      new Proxy(target, {
        get(obj, key) {
          if (key in obj) return obj[key as string];
          throw new Error(`read ${String(key)}`);
        },
      }) as unknown as TopicPageContent;
    assert.deepEqual(topicSectionAnchorProblems(untouchable({ sections: [{ heading: 'א', blocks: [] }], bodyFlow: [] })), []);
    assert.throws(
      () => topicSectionAnchorProblems(untouchable({ sections: [{ heading: 'א', anchor: 'a', blocks: [] }], bodyFlow: [] })),
      /read intro/
    );
  });

  it('loadTopicPage drops a bad anchor with one warning instead of throwing', (t) => {
    const warn = t.mock.method(console, 'warn', () => {});
    const section = (kiteGrade9 as unknown as TopicPageContent).sections[1];
    try {
      section.anchor = 'Bad Anchor';
      const page = loadTopicPage('kite-grade-9');
      assert.equal(page.sections[1].anchor, undefined);
      assert.ok(synthesizeBodyFlow(page).every((b) => b.type !== 'heading' || !b.anchor));
      loadTopicPage('kite-grade-9');
      assert.equal(warn.mock.calls.length, 1);
      assert.match(String(warn.mock.calls[0].arguments[0]), /^\[topic-pages\] kite-grade-9: section anchors dropped \(invalid section anchor "Bad Anchor"\)$/);
      // The hub cannot link a dropped anchor: plain text, no throw.
      assert.equal(resolvePrisaPage('kite-grade-9#bad-anchor-target', 9), null);
    } finally {
      delete section.anchor;
    }
    assert.equal(loadTopicPage('kite-grade-9').sections[1].anchor, undefined);
  });

  it('a section anchor reaches its heading, with or without a captured bodyFlow', () => {
    const withFlow = rawPage('kite-grade-9');
    assert.ok(withFlow.bodyFlow && withFlow.bodyFlow.length);
    withFlow.sections[1] = { ...withFlow.sections[1], anchor: 'common-mistakes' };
    validateTopicSectionAnchors(withFlow);
    const heading = synthesizeBodyFlow(withFlow).find((b) => b.type === 'heading' && b.text === 'טעויות נפוצות');
    assert.deepEqual(heading, { type: 'heading', text: 'טעויות נפוצות', anchor: 'common-mistakes' });

    const legacy = { ...withFlow, bodyFlow: undefined };
    const legacyHeading = synthesizeBodyFlow(legacy).find((b) => b.type === 'heading' && b.text === 'טעויות נפוצות');
    assert.deepEqual(legacyHeading, { type: 'heading', text: 'טעויות נפוצות', anchor: 'common-mistakes' });
    const plain = synthesizeBodyFlow(legacy).find((b) => b.type === 'heading' && b.text === 'הסבר ודוגמה');
    assert.deepEqual(plain, { type: 'heading', text: 'הסבר ודוגמה' });
  });

  it('rejects unsafe, reserved, duplicate and orphan anchors', () => {
    const base = rawPage('kite-grade-9');
    const withAnchors = (a: string | undefined, b?: string) => {
      const page = structuredClone(base);
      page.sections[0] = { ...page.sections[0], anchor: a };
      if (b !== undefined) page.sections[1] = { ...page.sections[1], anchor: b };
      return page;
    };
    assert.throws(() => validateTopicSectionAnchors(withAnchors('Bad Anchor')), /invalid section anchor/);
    assert.throws(() => validateTopicSectionAnchors(withAnchors('a/b')), /invalid section anchor/);
    assert.throws(() => validateTopicSectionAnchors(withAnchors('topic-levels')), /reserved topic- prefix/);
    assert.throws(() => validateTopicSectionAnchors(withAnchors('same', 'same')), /duplicate section anchor/);
    const orphan = structuredClone(base);
    orphan.sections[0] = { ...orphan.sections[0], heading: 'כותרת שלא מופיעה', anchor: 'orphan' };
    assert.throws(() => validateTopicSectionAnchors(orphan), /not on a rendered heading/);
    validateTopicSectionAnchors(withAnchors(undefined));
  });

  it('TopicPage renders the anchor as the H2 id', () => {
    const tpl = readFileSync(fromTest('../src/components/TopicPage.astro'), 'utf8');
    assert.match(tpl, /<h2 id=\{unit\.anchor\}>\{unit\.heading\}<\/h2>/);
    // SEO-4 moved the body-flow grouping out of TopicPage.astro into the shared CTA walk.
    const [section] = groupTopicBodyFlow([
      { type: 'heading', text: 'א', anchor: 'a' },
      { type: 'paragraph', text: 'ב' },
    ]);
    assert.deepEqual(section, { kind: 'section', heading: 'א', anchor: 'a', blocks: [{ type: 'paragraph', text: 'ב' }] });
  });
});

// Server-render the real components. Only the site shell (BaseLayout) and
// unrelated islands become <slot />; prisa components, data and libs are real.
const REAL = new Set(['PrisaMonthIndex.astro', 'PrisaUnitList.astro', 'grade-9-reduced.astro', 'TopicPage.astro', 'TopicWorksheetEditions.astro', 'TopicInline.astro']);
const componentCache = new Map<string, Promise<any>>();
function realComponent(rel: string) {
  if (!componentCache.has(rel)) {
    componentCache.set(rel, (async () => {
      const file = fromTest(rel);
      const options = { internalURL: 'astro/compiler-runtime', resultScopedSlot: true,
        renderScript: true, resolvePath: (specifier: string) => specifier };
      const bundled = await build({
        entryPoints: [file], bundle: true, write: false, format: 'esm', platform: 'node',
        plugins: [{ name: 'prisa-render-test', setup(builder) {
          builder.onResolve({ filter: /\?astro&type=style|\.css$/ }, (args) => ({ path: args.path, namespace: 'style' }));
          builder.onLoad({ filter: /.*/, namespace: 'style' }, () => ({ contents: '', loader: 'js' }));
          builder.onResolve({ filter: /\.astro$/ }, (args) => ({ path: resolve(args.resolveDir, args.path), namespace: 'astro-test' }));
          builder.onLoad({ filter: /.*/, namespace: 'astro-test' }, async (args) => {
            const source = REAL.has(basename(args.path)) ? readFileSync(args.path, 'utf8') : '<slot />';
            const compiled = await compileAstro(source, { ...options, filename: args.path });
            return { contents: compiled.code, loader: 'ts', resolveDir: dirname(args.path) };
          });
          builder.onResolve({ filter: /^astro\/(compiler-runtime|runtime\/)/ }, (args) => ({ path: pathToFileURL(require.resolve(args.path)).href, external: true }));
        } }],
      });
      return (await import(`data:text/javascript;base64,${Buffer.from(bundled.outputFiles[0].text).toString('base64')}`)).default;
    })());
  }
  return componentCache.get(rel)!;
}

async function render(rel: string, props: Record<string, unknown>, path = '/') {
  const container = await AstroContainer.create();
  const html = await container.renderToString(await realComponent(rel), {
    props, request: new Request(`https://prisa.test${path}`),
  });
  return parseHTML(`<!doctype html><html><body>${html}</body></html>`).document;
}

describe('rendered HTML', () => {
  it('/grade-9-reduced: one H1, nine month H2s, 39 units, a link per linked unit, ItemList JSON-LD', async () => {
    const doc = await render('../src/pages/grade-9-reduced.astro', {}, REDUCED_HUB_PATH);
    const track = loadPrisaTrack('g9m');
    const h1 = [...doc.querySelectorAll('h1')].map((h) => h.textContent.trim());
    assert.deepEqual(h1, ['מתמטיקה לכיתה ט׳ מצומצמת — דפי עבודה לפי הפריסה']);
    const months = [...doc.querySelectorAll('.prisa-hub__month')];
    assert.equal(months.length, 9);
    assert.deepEqual(months.map((m) => m.getAttribute('id')), track.months.map((m) => m.id));
    assert.equal(doc.querySelectorAll('.prisa-hub__month h2').length, 9);
    assert.equal(doc.querySelectorAll('li.prisa-unit').length, 39);
    assert.equal(doc.querySelectorAll('a.prisa-unit__link').length, track.linkedUnitCount);
    assert.equal(doc.querySelectorAll('li.prisa-unit[data-unit-linked="no"] a.prisa-unit__link').length, 0);
    const plain = [...doc.querySelectorAll('li.prisa-unit[data-unit-linked="no"]')].map((li) => li.getAttribute('data-unit-id'));
    assert.deepEqual(plain.sort(), track.months.flatMap((m) => m.units).filter((u) => !u.primary).map((u) => u.id).sort());
    for (const id of plain) assert.ok(NO_PAGE_UNITS.includes(id!), id!);
    const lds = [...doc.querySelectorAll('script[type="application/ld+json"]')].map((s) => JSON.parse(s.textContent));
    assert.deepEqual(lds.map((ld) => ld['@type']), ['ItemList', 'LearningResource']);
    for (const ld of lds) assert.deepEqual(validateJsonLdDocument(ld), []);
    assert.ok(lds[0].itemListElement.every((item: Record<string, unknown>) => typeof item.url === 'string'));
    assert.equal(new Set(lds[0].itemListElement.map((item: Record<string, unknown>) => item.url)).size, lds[0].numberOfItems);
    // The names come from the curriculum mapping, not verbatim from the layout PDF.
    const lead = [...doc.querySelectorAll('.prisa-hub__lead')].map((p) => p.textContent.replace(/\s+/g, ' ')).join(' ');
    assert.doesNotMatch(lead, /שם הנושא הוא השם בתוכנית הלימודים/);
    assert.match(lead, /שמות הנושאים כאן מפורטים לפעמים יותר מהנוסח שבפריסה/);
    assert.doesNotMatch(doc.querySelector('main')!.textContent, /בשמם הרשמי/);
    const hrefs = [...doc.querySelectorAll('a[href]')].map((a) => a.getAttribute('href')!);
    assert.ok(hrefs.includes('/worksheets?grade=9&track=red'));
    assert.ok(hrefs.includes('/grade-9#prisa'));
    for (const href of hrefs) {
      const reason = resolveSiteHref(href).reason;
      // Local pages, or the official prisa PDF on meyda.education.gov.il (media).
      assert.ok(reason === 'local' || (reason === 'media' && href.startsWith('https://meyda.education.gov.il/')), `${href} ${reason}`);
    }
    const text = doc.querySelector('main')!.textContent;
    assert.doesNotMatch(text, /\d\s*\/\s*\d/);
    assert.match(text, /במסלול המצומצם מציבים ערכים בלבד/);
  });

  it('grade 9 index: a "מסלול" radiogroup of two native radios switches רגילה and מצומצמת; the current month is open', async () => {
    const doc = await render('../src/components/PrisaMonthIndex.astro', { grade: 9, now: NOW }, '/grade-9');
    const section = doc.querySelector('section#prisa')!;
    assert.ok(section);
    assert.equal(section.querySelector('h2')!.textContent.trim(), 'לפי הפריסה');
    const lead = section.querySelector('.prisa-index__lead')!.textContent.replace(/\s+/g, ' ');
    assert.match(lead, /הנושאים מסודרים לפי פריסת ההוראה של משרד החינוך לכיתה ט׳ \(תשפ״ז\)/);
    assert.doesNotMatch(lead, /שם הנושא הוא השם בתוכנית הלימודים/);
    const groups = [...section.querySelectorAll('[role="radiogroup"]')];
    assert.equal(groups.length, 1);
    const group = groups[0];
    assert.equal(group.getAttribute('aria-label'), 'מסלול');
    assert.equal(group.querySelector('.prisa-switch__label')!.getAttribute('aria-hidden'), 'true');
    const radios = [...section.querySelectorAll('input[type="radio"]')];
    assert.deepEqual(radios.map((r) => r.getAttribute('id')), ['prisa-track-g9r', 'prisa-track-g9m']);
    assert.ok(radios.every((r) => group.contains(r) && r.getAttribute('name') === 'prisa-track-9'));
    assert.equal(radios[0].hasAttribute('checked'), true);
    assert.equal(radios[1].hasAttribute('checked'), false);
    // Each radio is followed by its own label (the CSS uses `input + label`).
    for (const radio of radios) {
      const label = radio.nextElementSibling!;
      assert.equal(label.tagName, 'LABEL');
      assert.equal(label.getAttribute('for'), radio.getAttribute('id'));
    }
    assert.deepEqual([...group.querySelectorAll('label.prisa-switch__option')].map((l) => l.textContent.trim()), ['ט׳ רגילה', 'ט׳ מצומצמת']);
    const panels = [...section.querySelectorAll('.prisa-index__panel')];
    assert.deepEqual(panels.map((p) => p.getAttribute('data-track')), ['g9r', 'g9m']);
    assert.ok(panels.every((p) => !group.contains(p)));
    assert.equal(panels[0].querySelectorAll('details.prisa-month').length, 9);
    assert.equal(panels[1].querySelectorAll('li.prisa-unit').length, 39);
    assert.equal(panels[0].querySelectorAll('li.prisa-unit').length, 48);
    const open = [...section.querySelectorAll('details[open]')].map((d) => d.getAttribute('id'));
    assert.deepEqual(open, ['prisa-g9r-m11', 'prisa-g9m-m11']);
    assert.equal(panels[1].querySelector(`a[href="${REDUCED_HUB_PATH}"]`)!.textContent.trim(), 'כל נושאי ט׳ מצומצמת בדף אחד');
    assert.equal(panels[0].querySelector(`a[href="${REDUCED_HUB_PATH}"]`), null);
    // "30°, 60°, 90°" is one unbroken LTR run inside the RTL link.
    const angles = section.querySelector('li[data-unit-id="st.g9r.right_triangle_30_60_90.theorem_and_converse"] a.prisa-unit__link')!;
    const math = [...angles.querySelectorAll('.prisa-math[dir="ltr"]')].map((m) => m.textContent);
    assert.deepEqual(math, ['30°, 60°, 90°']);
    assert.equal(/[\u2066-\u2069]/.test(angles.textContent), false);
    const css = readFileSync(fromTest('../src/styles/prisa-index.css'), 'utf8');
    assert.match(css, /\.prisa-index:has\(#prisa-track-g9r:checked\) \.prisa-index__panel\[data-track='g9m'\]/);
    assert.match(css, /\.prisa-index:has\(#prisa-track-g9m:checked\) \.prisa-index__panel\[data-track='g9r'\]/);
    assert.match(css, /\.prisa-switch__input:checked \+ \.prisa-switch__option/);
    assert.match(css, /\.prisa-switch__input:focus-visible \+ \.prisa-switch__option \{\s*outline: 3px solid #e6a534;/);
    assert.match(css, /min-height: 44px/);
    assert.match(css, /\.prisa-math \{\s*white-space: nowrap;/);
  });

  it('content train: /grade-9-reduced and the grade-9 index link topic 9/49 in ינואר with no code change', async () => {
    const id = 'st.g9m.equations.numeric_denominator';
    const href = '/equations-numeric-denominator-grade-9';
    const name = 'פתרון משוואות ממעלה ראשונה עם מכנה מספרי';
    // The reduced hub: the unit is a link in the January section, and its URL is in the ItemList.
    const hub = await render('../src/pages/grade-9-reduced.astro', {}, REDUCED_HUB_PATH);
    const row = hub.querySelector(`li.prisa-unit[data-unit-id="${id}"]`)!;
    assert.equal(row.getAttribute('data-unit-linked'), 'yes');
    const link = row.querySelector('a.prisa-unit__link')!;
    assert.equal(link.getAttribute('href'), href);
    assert.equal(link.textContent.trim(), name);
    assert.equal(row.querySelectorAll('a').length, 1, 'one page for this unit, no extra chips');
    const month = row.closest('.prisa-hub__month')!;
    assert.equal(month.getAttribute('id'), 'prisa-g9m-m01');
    assert.equal(month.getAttribute('data-month'), 'm01');
    assert.match(month.querySelector('h2')!.textContent.replace(/\s+/g, ' ').trim(), /^ינואר /);
    assert.equal(hub.querySelectorAll(`a[href="${href}"]`).length, 1);
    const itemList = [...hub.querySelectorAll('script[type="application/ld+json"]')].map((s) => JSON.parse(s.textContent))
      .find((ld) => ld['@type'] === 'ItemList');
    assert.equal(itemList.itemListElement.filter((item: Record<string, unknown>) => item.url === `https://www.noamdoronmath.co.il${href}`).length, 1);
    // Four reduced-track units still wait for a landing; they stay plain text.
    assert.equal(hub.querySelectorAll('li.prisa-unit[data-unit-linked="no"]').length, 4);
    assert.equal(loadPrisaTrack('g9m').linkedUnitCount, 35);
    // The grade-9 hub index: the same link, in the reduced panel only, inside its January month.
    const index = await render('../src/components/PrisaMonthIndex.astro', { grade: 9, now: NOW }, '/grade-9');
    const [regular, reduced] = [...index.querySelectorAll('.prisa-index__panel')];
    assert.deepEqual([regular.getAttribute('data-track'), reduced.getAttribute('data-track')], ['g9r', 'g9m']);
    assert.equal(regular.querySelectorAll(`a[href="${href}"]`).length, 0);
    const january = reduced.querySelector('details#prisa-g9m-m01')!;
    assert.equal(january.getAttribute('data-month'), 'm01');
    assert.match(january.querySelector('summary')!.textContent.replace(/\s+/g, ' ').trim(), /^ינואר /);
    const indexLinks = [...reduced.querySelectorAll(`a[href="${href}"]`)];
    assert.equal(indexLinks.length, 1);
    assert.ok(january.contains(indexLinks[0]));
    assert.equal(indexLinks[0].closest('li.prisa-unit')!.getAttribute('data-unit-id'), id);
  });

  it('grade 7 and 8 indexes have one track and no switch', async () => {
    for (const [grade, count] of [[7, 49], [8, 37]] as const) {
      const doc = await render('../src/components/PrisaMonthIndex.astro', { grade, now: new Date('2027-04-10T09:00:00Z') });
      assert.equal(doc.querySelectorAll('input[type="radio"]').length, 0);
      assert.equal(doc.querySelectorAll('.prisa-index__panel').length, 1);
      assert.equal(doc.querySelectorAll('li.prisa-unit').length, count);
      const open = [...doc.querySelectorAll('details[open]')].map((d) => d.getAttribute('data-month'));
      assert.deepEqual(open, grade === 7 ? ['m04'] : []);
    }
    const none = await render('../src/components/PrisaMonthIndex.astro', { grade: 3, now: NOW });
    assert.equal(none.querySelectorAll('section').length, 0);
  });

  it('a real topic landing still renders its H2s without ids', async () => {
    const doc = await render('../src/components/TopicPage.astro', { slug: 'kite-grade-9' }, '/kite-grade-9');
    const h2 = [...doc.querySelectorAll('.topic-page__section h2')];
    assert.ok(h2.length >= 3);
    assert.ok(h2.every((h) => !h.hasAttribute('id')));
  });
});

